import{_ as e,o as s,c as o,a2 as n}from"./chunks/framework.C2TvIV46.js";const m=JSON.parse('{"title":"はじめに","description":"","frontmatter":{},"headers":[],"relativePath":"ja/language/index.md","filePath":"ja/language/index.md"}'),l={name:"ja/language/index.md"};function t(r,a,g,d,c,i){return s(),o("div",null,[...a[0]||(a[0]=[n(`<h1 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h1><h2 id="まえがき" tabindex="-1">まえがき <a class="header-anchor" href="#まえがき" aria-label="Permalink to &quot;まえがき&quot;">​</a></h2><p>Megalo は 2008 年 3 月、Bungie の Tyson Green によって、Halo マルチプレイヤーのゲームルールをデータ駆動で実装する仕組みとして設計されました。エンドユーザー向けの Megalo ツールは当初から目標でしたが、Reach の当初開発期間中に Bungie が出荷することはありませんでした。</p><p>その後、Halo Studios が Halo Reach Editing Kit (HREK) とともに Bungie の <strong>MegaloEdit.exe</strong> を公開し、プレイヤーが独自のスクリプトを書けるようになりました。そのツールに付随するドキュメントはほとんどありません。</p><p>本ドキュメントは、Halo: Reach の Megalo を徹底的に調査した結果です。意図的に Bungie 自身の <a href="https://martinfowler.com/bliki/UbiquitousLanguage.html" target="_blank" rel="noreferrer">Ubiquitous Language</a> に従い — Bungie が名付けたであろう名前で、出荷スクリプトや MegaloEdit ツールに現れる同じ語彙を使っています。</p><p>過去 16 年間、Megalo を理解し、それで面白いゲームタイプを作り続けてきたモッダーの方々に感謝します。<a href="https://github.com/KornnerStudios" target="_blank" rel="noreferrer">kornman</a>、<a href="https://github.com/DavidJCobb/ReachVariantEditor" target="_blank" rel="noreferrer">DavidJCobb</a>、<a href="https://github.com/Pfoiffee" target="_blank" rel="noreferrer">Pfoiffee</a>、<a href="https://github.com/Sopitive" target="_blank" rel="noreferrer">Soptive</a>、そしてお会いしたことのない数え切れない方々へ。 — Codie</p><h2 id="megalo-とは" tabindex="-1">Megalo とは？ <a class="header-anchor" href="#megalo-とは" aria-label="Permalink to &quot;Megalo とは？&quot;">​</a></h2><p><strong>Megalo</strong> は、Bungie が Halo: Reach のマルチプレイヤールール用に作ったスクリプト言語です。作者は Megalo 対応エディタで人間が読める <code>.txt</code> スクリプトを編集します。Bungie は Reach とともに <strong>MegaloEdit.exe</strong> を出荷しました。無料のオープンソース代替として <strong>MegaloEvolved</strong> を推奨します。</p><p>Megalo は汎用言語ではありません。関数も、ループも、任意の式もありません — エンジンが公開する条件とアクションの語彙だけがあり、ゲームイベントで発火する <strong>トリガー</strong> にまとめられます。</p><p>Megalo プログラムは、ゲームタイプまたはカスタムマップバリアントを記述する <strong>要素</strong> の列です。</p><table tabindex="0"><thead><tr><th>概念</th><th>役割</th></tr></thead><tbody><tr><td><strong>要素 (Elements)</strong></td><td>スクリプトルートのブロック／リーフキーワード — メタデータ、チーム、変数、トリガー、HUD ウィジェット、文字列テーブルなど。詳しくは <a href="/MegaloEvolved/beta/docs/ja/language/syntax#the-element-model">要素モデル</a>。個別ページはサイドバーの <strong>Elements</strong> にあります。</td></tr><tr><td><strong>トリガー (Triggers)</strong></td><td>イベントハンドラ。各トリガーは <strong>条件</strong> が満たされたときに実行され、その後 <strong>アクション</strong> を実行します。<a href="/MegaloEvolved/beta/docs/ja/language/elements/trigger">trigger</a> を参照。</td></tr><tr><td><strong>条件 (Conditions)</strong></td><td><code>if</code>、<code>player_died</code>、<code>timer_expired</code>、<code>object_in_area</code> などの述語。<a href="/MegaloEvolved/beta/docs/ja/language/elements/trigger/condition">condition</a> を参照。</td></tr><tr><td><strong>アクション (Actions)</strong></td><td>命令文 — <code>set</code>、<code>create_object</code>、<code>hud_post_message</code>、<code>for_each</code>、ほか多数。<a href="/MegaloEvolved/beta/docs/ja/language/elements/trigger/action">action</a> を参照。</td></tr><tr><td><strong>変数 (Variables)</strong></td><td><code>number</code>、<code>timer</code>、<code>object</code>、<code>team</code>、<code>player</code> 型のスロット。global / team / player / object にスコープ。<a href="/MegaloEvolved/beta/docs/ja/language/variable-model">変数モデル</a> を参照。</td></tr><tr><td><strong>参照 (References)</strong></td><td>実行時にプレイヤー、チーム、オブジェクト、タイマー、カスタム変数を指す記号オペランド。<a href="/MegaloEvolved/beta/docs/ja/language/references">参照</a> を参照。</td></tr></tbody></table><h2 id="ソースファイル" tabindex="-1">ソースファイル <a class="header-anchor" href="#ソースファイル" aria-label="Permalink to &quot;ソースファイル&quot;">​</a></h2><p>Megalo エディタはスクリプトをプレーンテキストで保存します。典型的なゲームタイプスクリプトはメタデータで始まり、トリガーで終わります。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">include</span><span class="megalo-text"> </span><span class="megalo-string">&quot;strings/slayer_strings.txt&quot;</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">engine_data</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">name</span><span class="megalo-text"> slayer_title</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">description</span><span class="megalo-text"> slayer_description</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">icon</span><span class="megalo-text"> k_engine_icon_slayer</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">category</span><span class="megalo-text"> slayer</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">variables</span><span class="megalo-text"> </span><span class="megalo-keyword">global</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">local</span><span class="megalo-text"> </span><span class="megalo-type">number</span><span class="megalo-text"> </span><span class="megalo-variable">my_counter</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-enumMember">initialization</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">set</span><span class="megalo-text"> </span><span class="megalo-variable">my_counter</span><span class="megalo-text"> </span><span class="megalo-keyword">set_to</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>スクリプトは他のファイルを <code>include</code> できます。エディタはコンパイル前に include をマージします。一部のスクリプトはコンパイル済み親バリアントから継承する <code>base</code> も宣言します — <a href="/MegaloEvolved/beta/docs/ja/language/base-files">ベースファイル</a> を参照。</p><p>有効な条件とアクションの集合は Reach のビルドに依存します。ビルドごとの表は <a href="/MegaloEvolved/beta/docs/ja/versions/">Megalo バージョン</a> を参照。</p><h2 id="読み進め方" tabindex="-1">読み進め方 <a class="header-anchor" href="#読み進め方" aria-label="Permalink to &quot;読み進め方&quot;">​</a></h2><p>次の順で読むか、興味のあるトピックへジャンプしてください。</p><ol><li><a href="/MegaloEvolved/beta/docs/ja/language/syntax">構文とファイル形式</a> — コメント、トークン、命名、include、<a href="/MegaloEvolved/beta/docs/ja/language/syntax#the-element-model">要素モデル</a></li><li><a href="/MegaloEvolved/beta/docs/ja/language/base-files">ベースファイル</a> — コンパイル済み親バリアントからの継承</li><li><a href="/MegaloEvolved/beta/docs/ja/language/variable-model">変数モデル</a> — 型、スコープ、定数、組み込み</li><li><a href="/MegaloEvolved/beta/docs/ja/language/elements/trigger">trigger</a> — 種類、アクションスコープ、実行、<code>for_each</code></li><li><a href="/MegaloEvolved/beta/docs/ja/language/elements/trigger/condition">condition</a> — 比較、イベント、<code>and</code> / <code>or</code>、否定</li><li><a href="/MegaloEvolved/beta/docs/ja/language/elements/trigger/action">action</a> — オペコード、<code>set</code>、<a href="/MegaloEvolved/beta/docs/ja/language/enums/math-operations">数学演算</a>、アクション系統</li><li><a href="/MegaloEvolved/beta/docs/ja/language/references">参照</a> — player / team / object / timer オペランド。<a href="/MegaloEvolved/beta/docs/ja/language/enums/dynamic-strings">動的文字列</a> も参照</li><li><a href="/MegaloEvolved/beta/docs/ja/language/examples">サンプルスクリプト</a> — 最小スクリプトの注釈付きウォークスルー</li><li><a href="/MegaloEvolved/beta/docs/ja/language/object-lists">オブジェクトリスト</a> — 記号名のエンジン照合テーブル</li><li><a href="/MegaloEvolved/beta/docs/ja/language/compiler-settings">コンパイラ設定</a> — コンパイル時の厳格さと一時変数オーバーフロー</li></ol><p>TypeScript ライブラリの使い方は <a href="/MegaloEvolved/beta/docs/ja/guide/quick-start">利用ガイド</a> を参照。</p><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/MegaloEvolved/beta/docs/ja/versions/">Megalo バージョンとアクション表</a></li><li><a href="/MegaloEvolved/beta/docs/ja/guide/megalo-versions">Megalo バージョン (MCC と TU1)</a></li></ul>`,22)])])}const h=e(l,[["render",t]]);export{m as __pageData,h as default};
